#include <vector>
#include <algorithm>
#include <utility>

double interp(std::vector<double> xs, std::vector<double> ys, double x) {
    std::vector<std::pair<double, double>> p;
    for (size_t i = 0; i < xs.size(); ++i) p.push_back({xs[i], ys[i]});
    std::sort(p.begin(), p.end());
    std::vector<double> ux, uy;
    size_t i = 0;
    while (i < p.size()) {
        size_t j = i;
        double s = 0;
        while (j < p.size() && p[j].first == p[i].first) {
            s += p[j].second;
            ++j;
        }
        ux.push_back(p[i].first);
        uy.push_back(s / (j - i));
        i = j;
    }
    if (x <= ux.front()) return uy.front();
    if (x >= ux.back()) return uy.back();
    size_t k = std::upper_bound(ux.begin(), ux.end(), x) - ux.begin();
    double x0 = ux[k - 1], x1 = ux[k], y0 = uy[k - 1], y1 = uy[k];
    return y0 + (y1 - y0) * (x - x0) / (x1 - x0);
}
